import{_ as t,o,c as a,a3 as n}from"./chunks/framework.TWmUP5Ea.js";const d="/blank/screenshots/spelling.png",g=JSON.parse('{"title":"Spell check","description":"","frontmatter":{},"headers":[],"relativePath":"guide/spelling.md","filePath":"guide/spelling.md"}'),r={name:"guide/spelling.md"};function i(s,e,c,l,h,u){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="spell-check" tabindex="-1">Spell check <a class="header-anchor" href="#spell-check" aria-label="Permalink to &quot;Spell check&quot;">​</a></h1><p>Blank can underline the words it doesn&#39;t know with a wavy line, so a typo never slips into your finished piece. Spell check is off until you turn it on: some writers like a clean page while drafting and only proofread at the end.</p><img class="shot" src="'+d+'" alt="A misspelled word underlined in red, with the menu of suggestions open below it"><h2 id="turn-it-on" tabindex="-1">Turn it on <a class="header-anchor" href="#turn-it-on" aria-label="Permalink to &quot;Turn it on&quot;">​</a></h2><p>Press <code>Mod</code> <code>Alt</code> <code>S</code>, or right-click anywhere in the text and choose <strong>Enable Spell Check</strong>. Press the shortcut again, or click <strong>Spelling</strong> at the bottom right, to turn it off. Blank remembers your choice.</p><p>Blank checks the <a href="./autocorrect#language">language shown at the bottom right</a>. A word is checked once you finish it, so nothing is underlined while you are still typing it.</p><h2 id="fix-a-word" tabindex="-1">Fix a word <a class="header-anchor" href="#fix-a-word" aria-label="Permalink to &quot;Fix a word&quot;">​</a></h2><p>Right-click a word with a wavy line, or press <code>Mod</code> <code>Alt</code> <code>N</code> to jump to the next one, and choose what to do:</p><table tabindex="0"><thead><tr><th>Menu item</th><th>What it does</th></tr></thead><tbody><tr><td>A suggestion</td><td>Replaces the word. Capitals are kept, so <em>Teh</em> becomes <em>The</em>. <code>Mod</code> <code>Z</code> undoes it.</td></tr><tr><td><strong>Change All</strong> ▸ a suggestion</td><td>Replaces the word everywhere in the document, in one step you can undo.</td></tr><tr><td><strong>Ignore All</strong></td><td>Stops underlining the word in this document until you open or start another one.</td></tr><tr><td><strong>Add to Dictionary</strong></td><td>Accepts the word from now on, in every document.</td></tr></tbody></table><p>Right-click a word you added to change your mind:</p><table tabindex="0"><thead><tr><th>Menu item</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Remove from Dictionary</strong></td><td>Underlines the word again.</td></tr><tr><td><strong>Edit in Dictionary…</strong></td><td>Lets you correct the word you added, e.g. <em>Kubernets</em> to <em>Kubernetes</em>.</td></tr></tbody></table><p>The menu also has the usual editing commands: undo and redo, cut, copy, paste, paste as plain text, delete and select all. Hold <code>Shift</code> while you right-click for the system&#39;s own menu.</p><h2 id="use-the-keyboard" tabindex="-1">Use the keyboard <a class="header-anchor" href="#use-the-keyboard" aria-label="Permalink to &quot;Use the keyboard&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Shortcut</th></tr></thead><tbody><tr><td>Turn spell check on or off</td><td><code>Mod</code> <code>Alt</code> <code>S</code></td></tr><tr><td>Next misspelled word</td><td><code>Mod</code> <code>Alt</code> <code>N</code></td></tr><tr><td>Previous misspelled word</td><td><code>Mod</code> <code>Alt</code> <code>Shift</code> <code>N</code></td></tr><tr><td>Open the menu at the cursor</td><td><code>Shift</code> <code>F10</code> or the menu key</td></tr></tbody></table><p>In the menu, <code>↑</code> / <code>↓</code> move, <code>Enter</code> chooses, <code>→</code> opens a submenu and <code>Esc</code> closes it. Typing a letter jumps to the next item that starts with it.</p><h2 id="what-isn-t-checked" tabindex="-1">What isn&#39;t checked <a class="header-anchor" href="#what-isn-t-checked" aria-label="Permalink to &quot;What isn&#39;t checked&quot;">​</a></h2><ul><li>code, both inline and in code blocks</li><li>web and email addresses</li><li>words in capitals, like <em>NASA</em>, and words with digits, like <em>mp3</em>. You can <a href="./configuration#spell-check">check them too</a>.</li></ul><h2 id="languages" tabindex="-1">Languages <a class="header-anchor" href="#languages" aria-label="Permalink to &quot;Languages&quot;">​</a></h2><p>Blank checks spelling in about 80 languages and regional variants. The dictionaries for English (US), German, French and Spanish come with Blank. Any other one is downloaded the first time you check a text in that language, while the bottom right shows <strong>Spelling</strong> and the progress, and kept for offline use from then on.</p><p>To check a regional variant, type its code in the <a href="./autocorrect#language">language chooser</a>: <code>engb</code> for British English, <code>dech</code> for Swiss German, <code>ptpt</code> for Portuguese as written in Portugal, <code>esmx</code> for Mexican Spanish and so on. British, Canadian and Australian English, Austrian and Swiss German, and Portugal&#39;s Portuguese are also in the list you step through with <code>←</code> / <code>→</code>.</p><p>There is no dictionary for Finnish yet, and none that works for Turkish, Armenian, Latin, Mongolian, Nepali and Interlingua. For these, the bottom right shows <strong>No spelling</strong>.</p><details class="details custom-block"><summary>Where the dictionaries come from</summary><p>Blank uses the Hunspell dictionaries collected at <a href="https://github.com/wooorm/dictionaries" target="_blank" rel="noreferrer">wooorm/dictionaries</a>, each under its own open-source license. They are downloaded from the jsDelivr CDN, with unpkg as a fallback, and checked against a fingerprint built into Blank before they are used. Blank asks for nothing else, and your text never leaves your computer.</p></details><h2 id="your-dictionary" tabindex="-1">Your dictionary <a class="header-anchor" href="#your-dictionary" aria-label="Permalink to &quot;Your dictionary&quot;">​</a></h2><p>The words you add are kept in plain text files in the app config folder, one per language, e.g. <code>dictionaries/de.txt</code> for German, Austrian and Swiss German. Each line holds one word. You can edit, sync or back up these files; Blank reads them when you turn spell check on, change the language or start it.</p><p>A word added in lowercase is also accepted with a capital or in capitals: <em>blank</em> accepts <em>Blank</em> and <em>BLANK</em>. A word with capitals is accepted as written or in capitals: <em>iPhone</em> accepts <em>IPHONE</em>, but not <em>Iphone</em>.</p>',25)])])}const m=t(r,[["render",i]]);export{g as __pageData,m as default};
